select

from kol_sample_cost ksc


    ${params.sqlMap.default}
    and ksc.is_deleted = false


        ${params.permissionSql}

    ORDER BY


            ${item.field} ${item.sort}


    ksc.id desc

select

from kol_sample_cost ksc


    ksc.is_deleted = false

        and ksc.so_outstock_date >= #{startTime}


        and ksc.so_outstock_date < #{endTime}

WITH sampleBase as ( select sba.source_code, sba.source_id, sba.source_detail_id, sba.source_type, sba.so_detail_id, sba.partition_id, sba.type, sba.detail_id from (select kba.code as source_code, kba.id as source_id, kbad.id as source_detail_id, 'kolB2bApplication' as source_type, kba.type, sd.id as so_detail_id, si.code as so_code, si.partition_id, kbad.id as detail_id from kol_b2b_application kba inner join kol_b2b_application_detail kbad on kba.id = kbad.main_id and kbad.is_deleted = false inner join so_info si on si.source_id = kba.id and si.is_deleted = false inner join so_detail sd on sd.source_detail_id = kbad.id and sd.is_deleted = false where kba.is_deleted = false and kba.approve_status = 'approve'
union
select kba.code as source_code, kba.id as source_id, ksbad.id as source_detail_id, 'kolB2cApplication' as source_type, kba.sample_type as type, sbd.id as so_detail_id, sb.code as so_code, sbr.partition_id, kbad.id as detail_id from kol_b2c_application kba inner join kol_b2c_application_detail kbad on kba.id = kbad.main_id and kbad.is_deleted = false inner join kol_sub_b2c_application_detail ksbad on kbad.id = ksbad.source_detail_id and ksbad.is_deleted = false inner join so_b2c_detail sbd on sbd.source_detail_id = ksbad.id and sbd.is_deleted = false inner join so_b2c sb on sb.id = sbd.main_id and sb.is_deleted = false inner join so_b2c_receiver sbr on sbd.main_id = sbr.main_id and sbr.is_deleted = false where kba.is_deleted = false and kba.approve_status = 'approve' ) sba where sba.so_detail_id in
#{id}
), kolFeedback as ( select source_type, source_detail_id, array_to_string(array_agg(DISTINCT partner_id),',') as partner_id, array_to_string(array_agg(DISTINCT partner_nickname),',') as partner_nickname, array_to_string(array_agg(url order by sort, create_time, id),',') as url from ( select distinct on (source_type, source_detail_id, url_hash) source_type, source_detail_id, partner_id, partner_nickname, url, sort, create_time, id from kol_sample_cost_ref_feedback_url where is_deleted = false and (source_type, source_detail_id) in ( select source_type, detail_id from sampleBase ) order by source_type, source_detail_id, url_hash, sort, create_time, id ) kfu group by source_type, source_detail_id ) select sba.source_code, sba.source_id, sba.source_detail_id, sba.source_type, sba.so_detail_id, sba.partition_id, sba.type, sba.detail_id, sbd.tax_cost as "purchaseAverageCost", kfb.partner_id, kfb.partner_nickname, kfb.url as feedback_url from sampleBase sba left join kolFeedback kfb on sba.source_type = kfb.source_type and sba.detail_id = kfb.source_detail_id left join so_b2c_detail sbd on sba.source_type = 'kolB2cApplication' and sbd.id = sba.so_detail_id and sbd.is_deleted = false
